effect.shader:
// O `rand` do AM, letra por letra (as constantes em variáveis, como lá).
float rand(vec2 co)
{
    float a = 719.310;
    float b = 178.233;
    float c = 33758.5453;
    float dt= dot(co.xy ,vec2(a,b));
    float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

// UV → UV da tela com Y para baixo (o do AM). Na tela (`stage="screen"`) a entrada já é a tela, de pé (t = 0
// EMBAIXO); no filho de grupo, o `acTela` leva o buffer à tela do grupo. Nos dois casos, inverter o t — a mesma
// operação do AM (`1.0 - acScreenNorm.y`).
vec2 naTela(vec2 uv) {
    vec2 t = acEntradaDePe == 1 ? uv : acTela(uv);
    return vec2(t.x, 1.0 - t.y);
}

void main() {
    vec4 texColor = texture(inputImg, acScreenNorm);   // alfa reto
    // Os uniforms do AM com os nomes do Nova: a tela (px da composição), o `location` da camada (px do canto, Y para
    // baixo — o MESMO float do AM: com a camada no meio de uma composição de largura ímpar ele é ,5, e o pixel menos
    // ele cai em cima do inteiro; vindo de uma UV, o último bit mudaria o `floor`) e o conteúdo sem a escala.
    vec2 acScreenSize = acTamanhoDaTela;
    vec2 acLayerCenter = acCentroDaCamadaPx;
    vec2 acLayerSize = acTamanhoDaCamada;

    // Daqui até o `smoothstep`, a conta do AM na mesma ordem.
    vec2 st = floor((naTela(acScreenNorm)*acScreenSize)-acLayerCenter)/acLayerSize;
    float t = seed*3197.3791;
    t = mod(t,2.8)+2.7;
    float tileSize = min(acLayerSize.x, acLayerSize.y)/size;
    st.x *= acLayerSize.x/acLayerSize.y;
    st -= offset/1000.0;
    st *= tileSize;
    st.x /= stretch.x;
    st.y /= stretch.y;
    st = floor(st);

    float r = rand( st*t );
    float adjFade = max(fade,0.00001);
    float adjAmount = amount;
    adjAmount -= 0.5;
    adjAmount *= 1.0+(adjFade*2.0);
    adjAmount += 0.5;
    r = smoothstep(adjAmount-adjFade, adjAmount+adjFade, r);

    // O AM multiplica a cor PRÉ-multiplicada por r: a cor reta fica, o alfa é que muda.
    fragColor = vec4(texColor.rgb, texColor.a * r);
}
